extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var default_filter = ProjectSettings.get_setting("rendering/textures/canvas_textures/default_texture_filter")
	if not check("setting", default_filter == 1, "Il filtro predefinito del progetto deve essere Linear (1)"):
		return
	var scene := await instantiate_main_scene()
	if not check("scene", scene != null, "La scena principale space_station.tscn deve caricarsi correttamente"):
		return
	var bg := find_by_name(scene, "Background") as Sprite2D
	if not check("bg", bg != null, "Nella scena deve esserci il nodo Background"):
		return
	check("bg_filter", bg.texture_filter == CanvasItem.TEXTURE_FILTER_PARENT_NODE or bg.texture_filter == CanvasItem.TEXTURE_FILTER_LINEAR, "Lo sfondo deve avere resa morbida (Inherit o Linear)")
	var ship := find_by_name(scene, "Ship") as Sprite2D
	if not check("ship", ship != null, "Nella scena deve esserci il nodo Ship"):
		return
	check("ship_filter", ship.texture_filter == CanvasItem.TEXTURE_FILTER_PARENT_NODE or ship.texture_filter == CanvasItem.TEXTURE_FILTER_LINEAR, "L'astronave deve avere resa morbida (Inherit o Linear)")
	var capsule := find_by_name(scene, "Capsule") as Sprite2D
	if not check("capsule", capsule != null, "Nella scena deve esserci il nodo Capsule"):
		return
	check("capsule_filter", capsule.texture_filter == CanvasItem.TEXTURE_FILTER_NEAREST, "La capsula retrò deve avere il filtro impostato esplicitamente su Nearest (1)")
